module sliding_window_protocol #(parameter WINDOW_SIZE = 4, SEQ_WIDTH = 3)(  
    input clk,  
    input reset,  
    input send,  
    input ack,  
    input [SEQ_WIDTH-1:0] seq_num,  
    output reg [SEQ_WIDTH-1:0] last_sent_seq_num,  
    output reg [SEQ_WIDTH-1:0] last_ack_seq_num,  
    output reg retransmit  
);  
    reg [SEQ_WIDTH-1:0] current_window;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            last_sent_seq_num <= 0;  
            last_ack_seq_num <= 0;  
            current_window <= 0;  
            retransmit <= 0;  
        end else begin  
            if (send && (current_window < WINDOW_SIZE)) begin  
                last_sent_seq_num <= seq_num;  
                current_window <= current_window + 1;  
                retransmit <= 0;  
            end  
            if (ack) begin  
                last_ack_seq_num <= seq_num;  
                current_window <= current_window - 1;  
            end  
            if (seq_num == last_sent_seq_num) begin  
                retransmit <= 1;  
            end  
        end  
    end  
endmodule

