module pll (  
    input wire clk,  
    input wire reset,  
    input wire noisy_signal,  
    output reg recovered_signal  
);  
    reg [1:0] phase;  
    reg [7:0] filter;  
    reg vco;  

    // Phase Detector Logic  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase <= 2'b00;  
        end else begin  
            if (noisy_signal)  
                phase <= phase + 1;  
            else  
                phase <= phase - 1;  
        end  
    end  

    // Low-Pass Filter Logic  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            filter <= 8'b00000000;  
        end else begin  
            filter <= (filter + phase) >> 1;  
        end  
    end  

    // Voltage-Controlled Oscillator Logic  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            vco <= 0;  
        end else begin  
            vco <= filter[0];  
        end  
    end  

    // Output the recovered signal  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            recovered_signal <= 0;  
        end else begin  
            recovered_signal <= vco;  
        end  
    end  
endmodule

