module sliding_window_protocol (
    input clk,
    input reset,
    input send,
    input ack,
    output reg [3:0] packet_out,
    output reg [1:0] window_start
);
    parameter WINDOW_SIZE = 4;
    reg [1:0] next_window_start;
    reg [3:0] packet_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            packet_counter <= 0;
            window_start <= 0;
            packet_out <= 0;
        end else begin
            if (send && (packet_counter - window_start < WINDOW_SIZE)) begin
                packet_out <= packet_counter;
                packet_counter <= packet_counter + 1;
            end
            if (ack) begin
                window_start <= next_window_start;
            end
            next_window_start <= window_start + 1;
        end
    end
endmodule

