module pll(input clk,  
           input reset,  
           input signal_in,  
           output reg signal_out);  

    reg [1:0] phase;  
    reg [3:0] filter;  
    reg vco;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase <= 2'b00;  
            filter <= 4'b0000;  
            vco <= 1'b0;  
            signal_out <= 1'b0;  
        end else begin  
            // Phase Detector  
            if (signal_in)  
                phase <= phase + 1;  
            else  
                phase <= phase - 1;  

            // Low-Pass Filter  
            filter <= {filter[2:0], phase[1]};  

            // Voltage-Controlled Oscillator  
            if (filter[3])  
                vco <= ~vco;  

            // Output signal  
            signal_out <= vco;  
        end  
    end  
endmodule

