module divider (
    input clk,
    input reset,
    input start,
    input [7:0] dividend,
    input [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [7:0] count;
    reg [15:0] temp_dividend;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            quotient <= 8'b0;
            remainder <= 8'b0;
            count <= 8'b0;
            done <= 1'b0;
        end else if (start) begin
            temp_dividend <= {8'b0, dividend}; // Extend dividend
            quotient <= 8'b0;
            remainder <= 8'b0;
            count <= 8'b0;
            done <= 1'b0;
        end else if (count < 8) begin
            temp_dividend <= {temp_dividend[14:0], 1'b0}; // Shift left
            remainder <= {remainder[6:0], dividend[count]}; // Bring next bit
            if (temp_dividend >= {8'b0, divisor}) begin
                temp_dividend <= temp_dividend - {8'b0, divisor};
                quotient[count] <= 1;
            end
            count <= count + 1;
        end else begin
            remainder <= temp_dividend[7:0]; // Final remainder
            done <= 1'b1;
        end
    end
