module zero_crossing_detector (  
    input clk,  
    input rst,  
    input signal,  
    output reg pulse  
);  

reg signal_prev;  

always @(posedge clk or posedge rst) begin  
    if (rst) begin  
        signal_prev <= 0;  
        pulse <= 0;  
    end else begin  
        if (signal_prev == 0 && signal == 1) begin  
            pulse <= 1;  
        end else begin  
            pulse <= 0;  
        end  
        signal_prev <= signal;  
    end  
end  
endmodule

