module restoring_divider (  
    input clk,  
    input rst,  
    input [4:0] dividend,  
    input [2:0] divisor,  
    output reg [4:0] quotient,  
    output reg [4:0] remainder,  
    output reg done  
);  
    reg [4:0] divisor_extended;  
    reg [4:0] temp;  
    reg [2:0] count;  
    reg state;  // 0 for idle, 1 for working  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            quotient <= 0;  
            remainder <= 0;  
            temp <= 0;  
            count <= 0;  
            done <= 0;  
            state <= 0;  
        end else begin  
            case (state)  
                0: begin  // Idle  
                    if (count < 3) begin  
                        divisor_extended <= {2'b00, divisor};  // Extend divisor to match dividend size  
                        temp <= dividend;  
                        state <= 1;  
                    end  
                end  
                1: begin  // Working  
                    if (count < 5) begin  
                        temp <= {temp[3:0], 1'b0};  // Shift left  
                        if (temp >= divisor_extended) begin  
                            temp <= temp - divisor_extended;  
                            quotient[count] <= 1;  
                        end else begin  
                            quotient[count] <= 0;  
                        end  
                        count <= count + 1;  
                    end else begin  
                        remainder <= temp;  
                        done <= 1;  
                        state <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

