module SRT_Divider (
    input clk,
    input rst,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] temp_dividend;
    reg [15:0] temp_quotient;
    reg [3:0] state;
    reg [4:0] count;

    parameter IDLE = 4'b0000, 
              START = 4'b0001,
              DIVIDE = 4'b0010,
              SHIFT = 4'b0011,
              DONE = 4'b0100;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            quotient <= 0;
            remainder <= 0;
            done <= 0;
            count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (divisor != 0) begin
                        temp_dividend <= dividend;
                        temp_quotient <= 0;
                        count <= 16; // Assume we want to do 16 iterations
                        state <= START;
                    end
                end
                START: begin
                    state <= DIVIDE;
                end
                DIVIDE: begin
                    // Example of SRT division: Simplified for teaching purposes
                    if (count > 0) begin
                        // Perform SRT division step
                        if (temp_dividend >= divisor) begin
                            temp_dividend <= temp_dividend - divisor;
                            temp_quotient <= (temp_quotient << 1) | 1; // set LSB
                        end else begin
                            temp_quotient <= (temp_quotient << 1); // clear LSB
                        end
                        count <= count - 1;
                    end else begin
                        remainder <= temp_dividend;
                        quotient <= temp_quotient;
                        state <= DONE;
                    end
                end
                DONE: begin
                    done <= 1;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

