module pipeline_processor (  
    input clk,  
    input rst,  
    input [3:0] instruction,  
    output reg [7:0] result  
);  
    reg [7:0] registers [0:3];  
    reg [2:0] stage;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            stage <= 0;  
            result <= 0;  
            registers[0] <= 8'd0;  
            registers[1] <= 8'd0;  
            registers[2] <= 8'd0;  
            registers[3] <= 8'd0;  
        end else begin  
            case (stage)  
                3'd0: begin // Fetch  
                    // Fetch instruction here  
                    stage <= stage + 1;  
                end  
                3'd1: begin // Decode  
                    // Decode instruction here  
                    stage <= stage + 1;  
                end  
                3'd2: begin // Execute  
                    if (instruction[3:2] == 2'b00)  // ADD  
                        result <= registers[instruction[1:0]] + registers[instruction[1:0]];  
                    else if (instruction[3:2] == 2'b01) // SUB  
                        result <= registers[instruction[1:0]] - registers[instruction[1:0]];  
                    stage <= stage + 1;  
                end  
                3'd3: begin // Memory Access  
                    // Memory access stage (dummy)  
                    stage <= stage + 1;  
                end  
                3'd4: begin // Write Back  
                    // Write back result to register (dummy)  
                    registers[instruction[1:0]] <= result;  
                    stage <= stage + 1;  
                end  
                3'd5: begin // Hazard Handling 1  
                    // Handle hazards (dummy)  
                    stage <= stage + 1;  
                end  
                3'd6: begin // Hazard Handling 2  
                    // Handle hazards (dummy)  
                    stage <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

