module kalman_filter (
    input clk,
    input rst,
    input [15:0] measurement,
    output reg [15:0] estimated_output
);
    reg [15:0] x_hat; // estimated state
    reg [15:0] P;     // estimation error covariance
    reg [15:0] Q = 16'd1; // process noise covariance
    reg [15:0] R = 16'd10; // measurement noise covariance
    reg [15:0] K;     // Kalman gain

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_hat <= 16'd0;
            P <= 16'd1;
            estimated_output <= 16'd0;
        end else begin
            // Prediction step
            x_hat <= x_hat; // Assuming no control input (u_k = 0)
            P <= P + Q;

            // Update step
            K <= P / (P + R);
            x_hat <= x_hat + K * (measurement - x_hat);
            P <= (16'd1 - K) * P;

            estimated_output <= x_hat;
        end
    end
endmodule

module dram_cell (  
    input clk,  
    input we,  
    input [7:0] data_in,  
    output reg [7:0] data_out  
);  

    reg [7:0] memory;  

    always @(posedge clk) begin  
        if (we)  
            memory <= data_in;  
        else  
            data_out <= memory;  
    end  
endmodule

