module md5_hash(input clk, input [31:0] data_in, output reg [31:0] hash_out);  
    reg [31:0] hash;  
    parameter constant = 32'h5A5A5A5A;  

    always @(posedge clk) begin  
        hash <= (data_in ^ constant) << 3 | (data_in ^ constant) >> (32 - 3);  
        hash_out <= hash;  
    end  
endmodule

