module pipelined_processor (  
    input clk,  
    input reset,  
    input [31:0] instruction,  
    output reg [31:0] result  
);  

    reg [31:0] IF_ID_instruction;  
    reg [31:0] ID_EX_operand1, ID_EX_operand2;  
    reg [31:0] EX_MEM_result;  
    reg [31:0] MEM_WB_result;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            IF_ID_instruction <= 0;  
            ID_EX_operand1 <= 0;  
            ID_EX_operand2 <= 0;  
            EX_MEM_result <= 0;  
            MEM_WB_result <= 0;  
            result <= 0;  
        end else begin  
            // Stage 1: Instruction Fetch  
            IF_ID_instruction <= instruction;  

            // Stage 2: Instruction Decode  
            ID_EX_operand1 <= IF_ID_instruction[15:0]; // First operand  
            ID_EX_operand2 <= IF_ID_instruction[31:16]; // Second operand  

            // Stage 3: Execute  
            EX_MEM_result <= ID_EX_operand1 + ID_EX_operand2; // Simple addition  

            // Stage 4: Memory Access - No memory for this example, just pass through  
            MEM_WB_result <= EX_MEM_result;  

            // Stage 5: Write Back  
            result <= MEM_WB_result;  
        end  
    end  
endmodule

