module hamming_encoder(
    input [15:0] data_in,
    output reg [19:0] codeword
);
    always @(*) begin
        // Place data bits in the codeword
        codeword[0] = data_in[0];
        codeword[1] = data_in[1];
        codeword[2] = data_in[2];
        codeword[3] = data_in[3];
        codeword[4] = data_in[4];
        codeword[5] = data_in[5];
        codeword[6] = data_in[6];
        codeword[7] = data_in[7];
        codeword[8] = data_in[8];
        codeword[9] = data_in[9];
        codeword[10] = data_in[10];
        codeword[11] = data_in[11];
        codeword[12] = data_in[12];
        codeword[13] = data_in[13];
        codeword[14] = data_in[14];
        codeword[15] = data_in[15];

        // Calculate parity bits
        codeword[16] = data_in[0] ^ data_in[1] ^ data_in[3] ^ data_in[4] ^ data_in[6] ^ data_in[8] ^ data_in[10] ^ data_in[12] ^ data_in[14]; // P1
        codeword[17] = data_in[0] ^ data_in[2] ^ data_in[3] ^ data_in[5] ^ data_in[6] ^ data_in[9] ^ data_in[10] ^ data_in[13] ^ data_in[14]; // P2
        codeword[18] = data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[7] ^ data_in[6] ^ data_in[9] ^ data_in[11] ^ data_in[13] ^ data_in[15]; // P3
        codeword[19] = data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7] ^ data_in[8] ^ data_in[9] ^ data_in[10] ^ data_in[11] ^ data_in[12]; // P4
    end
endmodule

module viterbi_decoder(  
    input clk,  
    input rst,  
    input [1:0] encoded_bits,  
    output reg [3:0] decoded_bits,  
    output reg valid  
);  
    // State encoding  
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;  
    reg [1:0] state, next_state;  
    reg [3:0] path_metric [0:3];  
    integer i;  

    // State transition  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            state <= S0;  
        else  
            state <= next_state;  
    end  

    // Next state logic and output logic  
    always @(*) begin  
        case (state)  
            S0: begin  
                path_metric[0] = (encoded_bits == 2'b00) ? path_metric[0] + 1 : path_metric[0];  
                next_state = S1;  
            end  
            S1: begin  
                path_metric[1] = (encoded_bits == 2'b01) ? path_metric[1] + 1 : path_metric[1];  
                next_state = S2;  
            end  
            S2: begin  
                path_metric[2] = (encoded_bits == 2'b10) ? path_metric[2] + 1 : path_metric[2];  
                next_state = S3;  
            end  
            S3: begin  
                path_metric[3] = (encoded_bits == 2'b11) ? path_metric[3] + 1 : path_metric[3];  
                next_state = S0;  
                decoded_bits = (path_metric[0] > path_metric[1]) ? 4'b0001 : 4'b0010;  
                valid = 1;  
            end  
            default: begin  
                next_state = S0;  
                valid = 0;  
            end  
        endcase  
    end  
endmodule

