module temp_shutdown #(parameter THRESHOLD = 8'd75, parameter CYCLE_COUNT = 8'd5) (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] temperature,  
    output reg shutdown  
);  

    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 3'd0;  
            shutdown <= 1'b0;  
        end else begin  
            if (temperature > THRESHOLD) begin  
                if (count < CYCLE_COUNT)  
                    count <= count + 1;  
                else  
                    shutdown <= 1'b1;  
            end else begin  
                count <= 3'd0;  
                shutdown <= 1'b0;  
            end  
        end  
    end  
endmodule

module pitch_detector (
    input clk,
    input reset,
    input sample_in,
    output reg pitch_detected
);
    reg [15:0] count;
    reg [15:0] threshold = 16'd500; // Example threshold for pitch detection

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 16'd0;
            pitch_detected <= 1'b0;
        end else begin
            if (sample_in) begin
                count <= count + 1;
            end else begin
                count <= 16'd0; // Reset count if sample is low
            end

            // Simple pitch detection logic based on threshold
            if (count >= threshold) begin
                pitch_detected <= 1'b1;
            end else begin
                pitch_detected <= 1'b0;
            end
        end
    end
endmodule

