module sr_flip_flop(  
    input wire S,  
    input wire R,  
    input wire clk,  
    output reg Q,  
    output reg Qn  
);  
    always @(posedge clk) begin  
        if (S && !R) begin  
            Q <= 1'b1;  
        end else if (!S && R) begin  
            Q <= 1'b0;  
        end  
        Qn <= ~Q;  
    end  
endmodule

module counter_16bit (  
    input clk,  
    input reset,  
    input enable,  
    output reg [15:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            count <= 16'b0;  
        else if (enable) begin  
            if (count == 16'b1111111111111111)  
                count <= 16'b0;  
            else  
                count <= count + 1;  
        end  
    end  
endmodule

