module svm_classifier (
    input [4:0] x,  // 5-bit input vector for features
    output reg y    // Output class: 0 or 1
);
    reg signed [7:0] decision_value; // to handle the sum and bias

    always @(*) begin
        // Weights: w1=1, w2=-1, w3=1, w4=-1, w5=1; Bias: b=0
        decision_value = (1 * x[0]) + (-1 * x[1]) + (1 * x[2]) + (-1 * x[3]) + (1 * x[4]);

        // Apply decision function
        if (decision_value > 0) 
            y = 1; // Positive class
        else 
            y = 0; // Negative class
    end
endmodule

module fifo_queue #(parameter SIZE = 8, parameter WIDTH = 8) (
    input wire clk,
    input wire reset,
    input wire enqueue,
    input wire dequeue,
    input wire [WIDTH-1:0] data_in,
    output reg [WIDTH-1:0] data_out,
    output reg full,
    output reg empty
);
    reg [WIDTH-1:0] fifo [0:SIZE-1];
    reg [3:0] head, tail;
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            head <= 0;
            tail <= 0;
            count <= 0;
            full <= 0;
            empty <= 1;
            data_out <= 0;
        end else begin
            if (enqueue && !full) begin
                fifo[tail] <= data_in;
                tail <= (tail + 1) % SIZE;
                count <= count + 1;
                empty <= 0;
                if (count == SIZE - 1) full <= 1;
            end
            if (dequeue && !empty) begin
                data_out <= fifo[head];
                head <= (head + 1) % SIZE;
                count <= count - 1;
                full <= 0;
                if (count == 1) empty <= 1;
            end
        end
    end
endmodule

module wifi_state_machine (  
    input wire clk,  
    input wire reset,  
    input wire wifi_request,  
    input wire disconnect_request,  
    output reg [1:0] current_state  
);  
    // State encoding  
    localparam IDLE = 2'b00,  
               CONNECTING = 2'b01,  
               CONNECTED = 2'b10,  
               DISCONNECTED = 2'b11;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            current_state <= IDLE;  
        end else begin  
            case (current_state)  
                IDLE: begin  
                    if (wifi_request)  
                        current_state <= CONNECTING;  
                end  
                CONNECTING: begin  
                    current_state <= CONNECTED;  
                end  
                CONNECTED: begin  
                    if (disconnect_request)  
                        current_state <= DISCONNECTED;  
                end  
                DISCONNECTED: begin  
                    current_state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

