module serializer_16bit(  
    input wire clk,  
    input wire reset,  
    input wire [15:0] parallel_in,  
    output reg serial_out  
);  
    reg [3:0] bit_count;  
    reg [15:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_count <= 0;  
            serial_out <= 0;  
            shift_reg <= 0;  
        end else begin  
            if (bit_count < 16) begin  
                shift_reg <= parallel_in;  
                serial_out <= shift_reg[0];  
                shift_reg <= shift_reg >> 1;  
                bit_count <= bit_count + 1;  
            end  
        end  
    end  
endmodule

module pipelined_processor (  
    input clk,  
    input rst,  
    input [7:0] a,  
    input [7:0] b,  
    output reg [7:0] result  
);  
    reg [7:0] IF_ID_a, IF_ID_b;  
    reg [7:0] ID_EX_a, ID_EX_b;  
    reg [7:0] EX_MEM_sum;  
    reg [7:0] MEM_WB_result;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            IF_ID_a <= 0;  
            IF_ID_b <= 0;  
            ID_EX_a <= 0;  
            ID_EX_b <= 0;  
            EX_MEM_sum <= 0;  
            MEM_WB_result <= 0;  
            result <= 0;  
        end else begin  
            // Stage 1: Instruction Fetch  
            IF_ID_a <= a;  
            IF_ID_b <= b;  

            // Stage 2: Instruction Decode  
            ID_EX_a <= IF_ID_a;  
            ID_EX_b <= IF_ID_b;  

            // Stage 3: Execute  
            EX_MEM_sum <= ID_EX_a + ID_EX_b;  

            // Stage 4: Memory Access (no memory in this case, just a pass-through)  
            MEM_WB_result <= EX_MEM_sum;  

            // Stage 5: Write Back  
            result <= MEM_WB_result;  
        end  
    end  
endmodule

