module SRAM_Cell (  
    input [7:0] data,  
    input we,  
    input re,  
    output reg [7:0] q  
);  
    reg [7:0] memory;  

    always @(posedge we or posedge re) begin  
        if (we) begin  
            memory <= data;  
        end  
        if (re) begin  
            q <= memory;  
        end  
    end  
endmodule

module crc_generator(  
    input [3:0] data,  
    output [3:0] crc  
);  
    assign crc[3] = data[3] ^ data[2];  
    assign crc[2] = data[2] ^ data[1] ^ data[3];  
    assign crc[1] = data[1] ^ data[0] ^ data[2];  
    assign crc[0] = data[0] ^ data[1];  
endmodule

